let arguments raw =
  let request = Realization_request.of_json (get "request" raw) in
  let candidate = C.of_json (get "candidate" raw) in
  let history = Json.array (get "history" raw) |> List.map Execution_data.Input_frame.of_json in
  let until = match get "until" raw with Json.Null -> None | value -> Some (N.of_json value) in
  request,candidate,history,until
let run raw =
  let request,candidate,history,until = arguments raw in
  K.check ?until request candidate history
let same label expected actual =
  require (E.Check_result.fingerprint actual = E.Check_result.fingerprint expected &&
    Legacy_ascii.encode (E.Check_result.to_json actual) = Legacy_ascii.encode (E.Check_result.to_json expected)) label
let node_count value =
  let pending = ref [value] and count = ref 0 in
  while !pending <> [] do
    incr count;
    let value = List.hd !pending in pending := List.tl !pending;
    match value with
    | Json.Array values -> pending := List.rev_append values !pending
    | Json.Object fields -> count := !count + List.length fields;
        pending := List.rev_append (List.rev_map snd fields) !pending
    | _ -> ()
  done;
  !count
let () =
  require (Canonical.fingerprint literals = "e14cffc941bb593408936993fa6fdf1ea1e1d7c0a113fdaa47e5d019d0a7ff0e" && List.length cases = 12)
    "Independent full synthetic acceptance literal inventory changed";
  List.iter (fun raw ->
    let name = Json.string (get "name" raw) in
    let result = run raw in
    require (E.Check_result.fingerprint result = Json.string (get "fingerprint" raw))
      (name ^ ": complete result identity differs");
    require (Legacy_ascii.encode (E.Check_result.to_json result) = Legacy_ascii.encode (get "result" raw))
      (name ^ ": complete diagnostics, coverage, dependencies or counterexamples differ")) cases;
  let request,candidate,history,until = arguments (case "baseline") in
  let result,usage = K.check_with_usage ?until request candidate history in
  require (E.Check_result.passed result && usage.work_charged > 0) "Baseline acceptance or charged work was lost";
  let actual = case "in_band_actual_candidate" in
  let _,actual_candidate,_,_ = arguments actual in
  require (C.fingerprint actual_candidate <> C.fingerprint candidate && E.Check_result.passed (run actual))
    "An accepted actual candidate was replaced by the deterministic provenance witness";
  let silent = run (case "silent_actual_candidate") in
  require (E.Check_result.outcome silent = E.Fail && E.Check_result.counterexamples silent <> [])
    "Source provenance concealed a coherent candidate's actual response failure";
  let relocated_request,relocated_candidate,_,_ = arguments (case "relocated_original_source") in
  let relocated = run (case "relocated_original_source") in
  require (Realization_request.fingerprint relocated_request = Realization_request.fingerprint request &&
    C.fingerprint relocated_candidate = C.fingerprint candidate &&
    E.Check_result.fingerprint relocated <> E.Check_result.fingerprint result)
    "Exact source relocation was dropped or incorrectly changed semantic source/candidate identity";
  let parent = W.create ~profile:"literal.synthetic_acceptance" ~error_code:"literal_synthetic_parent" ~maximum:50_000_000 () in
  let repeated,nested = K.check_with_usage ?until ~parent request candidate history in
  same "Shared parent changed complete acceptance" result repeated;
  require (nested.work_charged = usage.work_charged && W.remaining parent = 50_000_000 - nested.work_charged)
    "Fresh lowering, provenance, candidate execution or publication escaped the shared allowance";
  let tiny = W.create ~profile:"literal.synthetic_acceptance" ~error_code:"literal_synthetic_parent" ~maximum:1 () in
  rejected "literal_synthetic_parent" (fun () -> K.check ?until ~parent:tiny request candidate history);
  List.iter (fun (code,limits) -> rejected code (fun () -> K.check ?until ~limits request candidate history))
    ["realization_work_limit",K.make_limits ~max_work:1 ();
     "realization_input_limit",K.make_limits ~max_request_bytes:1 ();
     "realization_report_limit",K.make_limits ~max_report_bytes:1 ();
     "realization_report_limit",K.make_limits ~max_report_nodes:1 ();
     "realization_monitor_limit",K.make_limits ~max_monitor_items:1 ()];
  rejected "realization_limits" (fun () -> K.make_limits ~max_work:50_000_001 ());
  rejected "realization_limits" (fun () -> K.make_limits ~max_request_bytes:(Limits.max_request_bytes + 1) ());
  (* The identity failure has no engine allocation: its complete measured work
     is therefore an exact success boundary, independent of engine holdbacks. *)
  let wrong_request,wrong_candidate,wrong_history,wrong_until = arguments (case "wrong_request_identity") in
  let failed,failed_usage = K.check_with_usage ?until:wrong_until wrong_request wrong_candidate wrong_history in
  require (E.Check_result.outcome failed = E.Fail && failed_usage.work_charged > 1) "Missing identity preflight failure";
  let exact = K.check ?until:wrong_until ~limits:(K.make_limits ~max_work:failed_usage.work_charged ())
      wrong_request wrong_candidate wrong_history in
  same "Exact preflight work boundary changed the full failure report" failed exact;
  rejected "realization_work_limit" (fun () -> K.check ?until:wrong_until
    ~limits:(K.make_limits ~max_work:(failed_usage.work_charged - 1) ()) wrong_request wrong_candidate wrong_history);
  rejected "realization_horizon" (fun () -> K.check ~until:(N.of_int (-1)) wrong_request wrong_candidate wrong_history);
  let skeleton = Json.Object ["request",Json.Null;"candidate",Json.Null;"history",Json.Array [];
      "until",(match wrong_until with None -> Json.Null | Some value -> N.to_json value)] in
  let fragments = skeleton :: Realization_request.to_json wrong_request :: C.to_json wrong_candidate ::
      List.map Execution_data.Input_frame.to_json wrong_history in
  let request_bytes = List.fold_left (fun total raw -> total + String.length (Canonical.encode raw) + 1) 0 fragments in
  same "Exact complete input envelope boundary changed failure" failed
    (K.check ?until:wrong_until ~limits:(K.make_limits ~max_request_bytes:request_bytes ())
      wrong_request wrong_candidate wrong_history);
  rejected "realization_input_limit" (fun () -> K.check ?until:wrong_until
    ~limits:(K.make_limits ~max_request_bytes:(request_bytes - 1) ()) wrong_request wrong_candidate wrong_history);
  let report = E.Check_result.to_json failed in
  let dependencies = get "dependencies" report in
  let report_bytes = String.length (Legacy_ascii.encode dependencies) + String.length (Legacy_ascii.encode report) + 2 in
  let report_nodes = node_count dependencies + node_count report in
  same "Exact cumulative dependency/report byte boundary changed failure" failed
    (K.check ?until:wrong_until ~limits:(K.make_limits ~max_report_bytes:report_bytes ())
      wrong_request wrong_candidate wrong_history);
  rejected "realization_report_limit" (fun () -> K.check ?until:wrong_until
    ~limits:(K.make_limits ~max_report_bytes:(report_bytes - 1) ()) wrong_request wrong_candidate wrong_history);
  same "Exact cumulative dependency/report node boundary changed failure" failed
    (K.check ?until:wrong_until ~limits:(K.make_limits ~max_report_nodes:report_nodes ())
      wrong_request wrong_candidate wrong_history);
  rejected "realization_report_limit" (fun () -> K.check ?until:wrong_until
    ~limits:(K.make_limits ~max_report_nodes:(report_nodes - 1) ()) wrong_request wrong_candidate wrong_history);
  let failure_parent = W.create ~profile:"literal.synthetic_failure" ~error_code:"literal_synthetic_failed_parent" ~maximum:50_000_000 () in
  let first,first_usage = K.check_with_usage ?until:wrong_until ~parent:failure_parent wrong_request wrong_candidate wrong_history in
  let after_first = W.remaining failure_parent in
  let second,second_usage = K.check_with_usage ?until:wrong_until ~parent:failure_parent wrong_request wrong_candidate wrong_history in
  same "Repeated identity failure changed its result" first second;
  require (first_usage.work_charged = second_usage.work_charged && after_first = 50_000_000 - first_usage.work_charged &&
    W.remaining failure_parent = after_first - second_usage.work_charged)
    "Failed checks reused unchecked authority or reset shared work capacity";
  let first = List.hd history in
  let rec cyclic_history = first :: cyclic_history in
  rejected "realization_input_limit" (fun () -> K.check ?until request candidate cyclic_history);
  same "Failure or cyclic input contaminated an independent synthetic check" result (K.check ?until request candidate history);
  print_endline "synthetic acceptance: 12 complete independent Python results, actual-candidate execution, source coordinates, rejection precedence, exact/shared bounds and failure isolation checked"

let () =
  let report = E.Check_result.to_json (run (case "baseline")) in
  let keys value = List.map fst (Json.object_fields value) in
  let dependencies = get "dependencies" report in
  require (keys dependencies = ["behavior";"behavior_artifact";"contract";"domain";"target";
    "mechanism";"observation_map";"history";"horizon";"checker";"model_runner";"reference_evaluator";"settings"])
    "Synthetic checking moved replaced settings ahead of original dependencies";
  require (keys (get "settings" dependencies) =
    ["scope";"intended_use";"human_admission_policy";"time";"response";"nonvacuity";"contact_loss";
     "coverage";"max_microsteps";"synthetic_acceptance";"synthetic_profile";"synthetic_candidate";
     "realization_request";"generator_configuration";"catalog";"required_coverage"])
    "Synthetic settings differ from original mapping-unpack insertion order"
